import{d as g,C as t,o as b,c,j as a,a as r,E as o,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十一章","description":"从知不知、不知知的对照读认知限度，辨病病的动词与名词及圣人不病之意。","frontmatter":{"title":"道德经第七十一章","description":"从知不知、不知知的对照读认知限度，辨病病的动词与名词及圣人不病之意。","category":"guide","aliases":["道德经第七十一章","老子第七十一章","dao de jing chapter 71"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-71.md","filePath":"daoism/dao-de-jing/chapter-71.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-71.md"},y=g({...m,setup(u){const i=[{id:"knowing-what-is-not-known",label:"知不知，上",showLabel:!0,sentences:[[{text:"知",glossary:"zhi"},"不",{text:"知",glossary:"zhi"},"，",{text:"上",glossary:"shang"},"；"]],note:["【白话】知道自己还有不知道的地方，是较高明的认识态度。这里先从承认所知有边界来理解知不知，而不把不知道本身当成成就。","【读法】上用于评说这种态度较好，不是说身居上位。承认不知之后，仍可以继续求证和学习；重点是不给尚未明白的事情冒充一个已知答案。"]},{id:"mistaking-limited-knowledge-for-certainty",label:"不知知，病",showLabel:!0,sentences:[["不",{text:"知",glossary:"zhi"},{text:"知",glossary:"zhi"},"，",{text:"病",glossary:"bing"},"。"]],note:["【白话】不知道却自以为知道，是一种弊病。依王弼的解释，尤其要警惕：不明白自己的知有不足凭任之处，却把它当作足够的依靠。","【王弼注择要】「不知知之不足任，则病也。」注将问题放在不知知的限度，不只是承认某一项事实暂时不清楚。","【读法】前一句白话先列通常的不知而自以为知读法，再说明所据王注的重心。两者都可提示认识的限度，但不能因此推成一切知识都无用。"]},{id:"regarding-the-fault-as-a-fault",label:"夫唯病病",showLabel:!0,sentences:[["夫唯",{text:"病",glossary:"bing-regard"},{text:"病",glossary:"bing"},"，是以不",{text:"病",glossary:"bing"},"。"]],note:["【白话】正因为能把这种弊病看作弊病、认真正视它，所以才不陷于这种弊病。前一个病是以为病，后一个病是所指的弊病。","【读法】本句把开头的认识态度推进到自我检查。发现自己不知道，若仍只是口头谦虚而不改变判断方式，便还没有走到病病这一层。"]},{id:"the-sage-and-recognized-limits",label:"圣人不病",showLabel:!0,sentences:[["圣人不",{text:"病",glossary:"bing"},"，以其",{text:"病",glossary:"bing-regard"},{text:"病",glossary:"bing"},"，是以不",{text:"病",glossary:"bing"},"。"]],note:["【白话】圣人没有这种弊病，正因为他把这种弊病当作需要正视的问题，所以不被它困住。不病的理由，仍回到以其病病。","【读法】这里没有说圣人掌握了一切知识。末句重复不病，是为了把圣人的认识态度与前文相接；病在本章指认识上的弊病，不是身体永不患病。","【读法】所据本章仅在不知知病之后见上述王注，其余段落依经文解释，不补造逐句古注。"]}],n=[{id:"zhi",term:"知",sense:2,pinyin:["zhī"]},{id:"shang",term:"上",sense:2},{id:"bing",term:"病",sense:1},{id:"bing-regard",term:"病",sense:2}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return b(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十一章",tabindex:"-1"},[r("道德经第七十一章 "),a("a",{class:"header-anchor",href:"#道德经第七十一章","aria-label":'Permalink to "道德经第七十一章"'},"​")],-1)),o(s,{title:"知道自己有所不知，为什么反而是上",summary:"本章不比较谁知道得最多，而是追问人怎样对待自己的不知。知不知与不知知先构成对照，随后用病病说明：能把认识上的弊病当作问题，才可能不被它遮蔽。王弼特别指出，要知道知本身也有不足凭任之处。",points:[{label:"先读",text:"知不知先按知道自己有所不知理解，上是较高明的评价。"},{label:"再辨",text:"病病前一病作动词，后一病是弊病，不是两个身体疾病的叠加。"},{label:"后看",text:"圣人不病承接以其病病，所强调的是面对认知局限的态度。"}],hint:"知在本章读 zhī，上读 shàng，病读 bìng。病病要区分以为弊病与弊病本身两个用法。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"知不知，上；不知知，病。",tone:"先辨认识的态度",guide:"知道自己的边界，与把有限的知当作足够的凭依，构成全章起点。"},{text:"夫唯病病，是以不病。",tone:"两个病各有用法",guide:"以为弊病的动词，作用于弊病这一名词，落在能否正视问题。"},{text:"圣人不病，以其病病，是以不病。",tone:"圣人也从自检说起",guide:"不病有其理由，不靠自称高明或声称无所不知。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:n}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-知不知是在赞美无知吗" tabindex="-1">象：知不知是在赞美无知吗？ <a class="header-anchor" href="#象-知不知是在赞美无知吗" aria-label="Permalink to &quot;象：知不知是在赞美无知吗？&quot;">​</a></h3><p>它先说的是知道自己有所不知，不是把不学习当作较高明。王注又强调知之不足任，提醒人即使有知识，也要看它在当前问题上是否足够、是否适用。</p><h3 id="理-为什么正视弊病能与不病相连" tabindex="-1">理：为什么正视弊病能与不病相连？ <a class="header-anchor" href="#理-为什么正视弊病能与不病相连" aria-label="Permalink to &quot;理：为什么正视弊病能与不病相连？&quot;">​</a></h3><p>若把局限当作已经解决的问题，就难以修正判断；能识别并认真对待局限，才有调整的入口。本章以病病说这种转向，不是说只要命名一个问题就已经消除了它。</p><h3 id="用-今天可以怎样实践这种认识态度" tabindex="-1">用：今天可以怎样实践这种认识态度？ <a class="header-anchor" href="#用-今天可以怎样实践这种认识态度" aria-label="Permalink to &quot;用：今天可以怎样实践这种认识态度？&quot;">​</a></h3><p>作出重要判断前，写清已经确认的事实、尚缺的信息和会改变结论的条件。遇到新证据时允许更新，也让别人看见自己的不确定之处。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把知道拆到具体问题上。</strong> 熟悉一个领域，不等于每个相关问题都有现成答案。说明这次判断凭什么、仍缺什么，比只说自己懂或不懂更能帮助合作。</p><p><strong>让修正有入口。</strong> 提前约定何时复核、哪些迹象需要重新判断，使承认局限能接到行动。病病的启发，可以从这样一项可执行的自检开始。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近哪一次把熟悉感当成了足够的依据？若认真承认知之不足任，我还需要补哪项信息、听取谁的质疑？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 008a 电子录文核对；开头依知不知与不知知拆为两段。</li><li>知统一取认识义并覆盖注音为 zhī；上取较高明的评价义，病病的动词与名词分别绑定字典义项。</li><li>不知知先列通常的不知而自以为知读法，再列王弼不知知之不足任则病也的解释，不把两者当作毫无差别的逐字译文。</li><li>所据本章仅见上述一条王注，其他段落标为读法。古注节引转简体并加标点，尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，008a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
